class Solution:
    def binarySearchableNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0
        for i in range(n):
            ok = True
            for j in range(i):
                if nums[j] > nums[i]:
                    ok = False
                    break
            if ok:
                for k in range(i + 1, n):
                    if nums[k] < nums[i]:
                        ok = False
                        break
            if ok:
                count += 1
        return count

