class Solution {
public:
    int binarySearchableNumbers(vector<int>& nums) {
        int n = nums.size(), count = 0;
        for (int i = 0; i < n; i++) {
            bool ok = true;
            for (int j = 0; j < i && ok; j++)
                if (nums[j] > nums[i]) ok = false;
            for (int k = i + 1; k < n && ok; k++)
                if (nums[k] < nums[i]) ok = false;
            if (ok) count++;
        }
        return count;
    }
};

