class Solution:
    def binarySearchableNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        pre = [0] * n
        mx = float('-inf')
        for i in range(n):
            pre[i] = mx
            mx = max(mx, nums[i])
        suf = [0] * n
        mn = float('inf')
        for i in range(n - 1, -1, -1):
            suf[i] = mn
            mn = min(mn, nums[i])
        return sum(1 for i in range(n) if pre[i] < nums[i] < suf[i])

