class Solution {
public:
    int binarySearchableNumbers(vector<int>& nums) {
        int n = nums.size();
        vector<int> pre(n, INT_MIN), suf(n, INT_MAX);
        for (int i = 1; i < n; i++) pre[i] = max(pre[i - 1], nums[i - 1]);
        for (int i = n - 2; i >= 0; i--) suf[i] = min(suf[i + 1], nums[i + 1]);
        int res = 0;
        for (int i = 0; i < n; i++)
            if (pre[i] < nums[i] && nums[i] < suf[i]) res++;
        return res;
    }
};

