class Solution {
    public int binarySearchableNumbers(int[] nums) {
        int n = nums.length;
        int[] pre = new int[n], suf = new int[n];
        pre[0] = Integer.MIN_VALUE;
        suf[n - 1] = Integer.MAX_VALUE;
        for (int i = 1; i < n; i++) pre[i] = Math.max(pre[i - 1], nums[i - 1]);
        for (int i = n - 2; i >= 0; i--) suf[i] = Math.min(suf[i + 1], nums[i + 1]);
        int res = 0;
        for (int i = 0; i < n; i++)
            if (pre[i] < nums[i] && nums[i] < suf[i]) res++;
        return res;
    }
}

